                                        const angle = (60 * i + 30) * Math.PI / 180;
                                        const hx = pt.cx + Math.cos(angle) * hexSize;
                                        const hy = pt.cy + Math.sin(angle) * hexSize * 0.8; // Perspective factor matches center projection
