        bTween.play();

        // 3. Move Unit
        const t = new Konva.Tween({
            node: visualGroupRef.current,
            y: -1000,
            opacity: 0,
            duration: 3,
            easing: Konva.Easings.EaseIn,
        });
        t.play();

        return () => {
            t.destroy();
            bTween.destroy();
            beam.destroy();
        };
    }
  }, [evacuationActive]);

  // --- PRODUCTION GRADE QUALITY PROGRESSION HUD & PARTICLES SYSTEM ---
  useEffect(() => {
    const ptsGroup = particlesGroupRef.current;
    if (!isGrowing) {
