const getLevelIndexFromId = (id?: string | null): number => {
    if (!id) return 1;
    const parts = id.split('.');
    if (parts.length === 2) {
        const series = parseInt(parts[0], 10);
        const offset = parseInt(parts[1], 10);
        if (!isNaN(series) && !isNaN(offset)) {
            return (series - 1) * 10 + offset;
        }
    }
    return 1;
};

