                                                    <div className="flex flex-col min-w-0">
                                                        <span className="text-[7.5px] sm:text-[8px] font-black text-slate-500 uppercase leading-none truncate">{language === 'RU' ? 'РЕСУРС ХОДОВ' : 'MOVES BUDGET'}</span>
