export default React.memo(TopStatsBar);

/**
 * Advanced Procedural Audio Synthesizer for HexQuest
 * Engine: "Nebula V2"
 * Features: FM Synthesis, Generative Arrangement, Chord Progressions, Dynamic Mixing
 */

type SoundType = 
  | 'UI_HOVER' 
  | 'UI_CLICK' 
  | 'MOVE' 
  | 'ERROR' 
  | 'SUCCESS' 
  | 'LEVEL_UP' 
  | 'COIN' 
  | 'GROWTH_START' 
  | 'COLLAPSE' 
  | 'CRACK' 
  | 'WARNING'
  | 'FIREWORK'
  | 'TELEPORT';

// --- MUSIC THEORY CONSTANTS ---

const ROOT_FREQUENCIES = {
    C2: 65.41,
    Db2: 69.30,
    D2: 73.42,
    Eb2: 77.78,
    E2: 82.41,
    F2: 87.31,
    G2: 98.00,
    Ab2: 103.83,
    A2: 110.00,
    Bb2: 116.54,
    B2: 123.47
};

// Scales defined by semitone intervals
const SCALES = {
    MINOR: [0, 2, 3, 5, 7, 8, 10],      // Aeolian
    DORIAN: [0, 2, 3, 5, 7, 9, 10],     // Sci-Fi / Hopeful
    PHRYGIAN: [0, 1, 3, 5, 7, 8, 10],   // Dark / Tension
    LYDIAN: [0, 2, 4, 6, 7, 9, 11],     // Space / Floating
    HARMONIC_MINOR: [0, 2, 3, 5, 7, 8, 11] // Exotic / Ancient
};

// Arrangement Sections
enum Section {
    INTRO,
    BUILD,
    MAIN,
    BREAKDOWN,
    OUTRO
}

interface MusicalContext {
    rootFreq: number;
    scale: number[];
    bpm: number;
    chordProgression: number[][]; // Array of chord degrees (e.g. [0, 4, 5, 3] relative to scale)
    currentChordIndex: number;
    intensity: number; // 0.0 to 1.0
}

class AudioService {
  private ctx: AudioContext | null = null;

  // Mix Buses
  private masterCompressor: DynamicsCompressorNode | null = null;
  private masterGain: GainNode | null = null;
  private musicBus: GainNode | null = null;
  private sfxBus: GainNode | null = null;

  // FX Sends
  private reverbNode: ConvolverNode | null = null;
  private delayNode: DelayNode | null = null;
  private delayFeedback: GainNode | null = null;

  // State
  private portalHumNode: { osc: OscillatorNode; lfo: OscillatorNode; filter: BiquadFilterNode; lfoGain: GainNode; gain: GainNode } | null = null;
  private isMusicMuted: boolean = false;
  private isSfxMuted: boolean = false;
  private musicRunning: boolean = false;
  private whiteNoiseBuffer: AudioBuffer | null = null;

  // Scheduler
  private lookahead = 25.0; // ms
  private scheduleAheadTime = 0.1; // s
  private nextNoteTime = 0.0;
  private current16thNote = 0;
  private timerID: number | null = null;
  private schedulerId: number = 0; // Generation ID to kill old loops
  private stopTimerID: any = null;

  // Composition State
  private context: MusicalContext = {
      rootFreq: ROOT_FREQUENCIES.F2,
      scale: SCALES.MINOR,
      bpm: 110,
      chordProgression: [[0, 2, 4], [5, 7, 9], [3, 5, 7], [4, 6, 8]], // I, VI, IV, V approx
      currentChordIndex: 0,
      intensity: 0.5
  };

  private arrangementState = {
      section: Section.INTRO,
      barCount: 0,
      totalBars: 0
  };

  // Dynamic Pattern State (Regenerated every few bars)
  private patterns = {
      kick: [] as boolean[],
      hat: [] as boolean[],
      perc: [] as boolean[],
      bass: [] as number[], // Scale degrees
      arp: [] as number[]   // Scale degrees
  };

  constructor() {
      this.handleUnlock = this.handleUnlock.bind(this);

      // Safe fallback load of persistent audio settings to avoid initial state mismatch
      try {
          if (typeof window !== 'undefined' && window.localStorage) {
              const raw = localStorage.getItem('hexquest-storage-v4');
              if (raw) {
                  const parsed = JSON.parse(raw);
                  if (parsed && parsed.state) {
                      if (typeof parsed.state.isMusicMuted === 'boolean') {
                          this.isMusicMuted = parsed.state.isMusicMuted;
                      }
                      if (typeof parsed.state.isSfxMuted === 'boolean') {
                          this.isSfxMuted = parsed.state.isSfxMuted;
                      }
                  }
              }
          }
      } catch (e) {
          // localStorage might be unavailable in private browsing or iframe restrictions
          console.warn('AudioService local storage load failed', e);
      }
  }

  // IOS AUDIO UNLOCK HANDLER
  private handleUnlock() {
      if (this.ctx && this.ctx.state !== 'running') {
          this.ctx.resume().then(() => {
              // Play a silent buffer to physically wake up the iOS audio thread
              const buffer = this.ctx!.createBuffer(1, 1, 22050);
              const source = this.ctx!.createBufferSource();
              source.buffer = buffer;
              source.connect(this.ctx!.destination);
              source.start(0);
          }).catch(e => console.error("Audio resume failed", e));
      }
  }

  private init() {
    if (!this.ctx) {
      const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
      this.ctx = new AudioContextClass();

      // Precompute a global white noise buffer to prevent CPU-heavy synchronous array generation
      const noiseLength = this.ctx.sampleRate * 2; // 2 seconds of noise
      this.whiteNoiseBuffer = this.ctx.createBuffer(1, noiseLength, this.ctx.sampleRate);
      const noiseData = this.whiteNoiseBuffer.getChannelData(0);
      for (let i = 0; i < noiseLength; i++) {
          noiseData[i] = Math.random() * 2 - 1;
      }

      // 1. Master Chain: Compressor -> Master Gain -> Destination
      this.masterCompressor = this.ctx.createDynamicsCompressor();
      this.masterCompressor.threshold.value = -8; 
      this.masterCompressor.knee.value = 40;
      this.masterCompressor.ratio.value = 4; 
      this.masterCompressor.attack.value = 0.05; 
      this.masterCompressor.release.value = 0.1;

      this.masterGain = this.ctx.createGain();
      this.masterGain.gain.value = 1.0;

      this.masterCompressor.connect(this.masterGain);
      this.masterGain.connect(this.ctx.destination);

      // 2. Buses
      this.musicBus = this.ctx.createGain();
      // Enforce mute state on initialization
      this.musicBus.gain.value = this.isMusicMuted ? 0 : 0.5;
      this.musicBus.connect(this.masterCompressor);

      this.sfxBus = this.ctx.createGain();
      this.sfxBus.gain.value = this.isSfxMuted ? 0 : 0.5; 
      this.sfxBus.connect(this.masterCompressor);

      // 3. FX: Reverb (Space)
      this.reverbNode = this.ctx.createConvolver();
      const ir = this.createReverbImpulse(3.0);
      if (ir) this.reverbNode.buffer = ir;

      const reverbGain = this.ctx.createGain();
      reverbGain.gain.value = 0.4;
      this.reverbNode.connect(reverbGain);
      reverbGain.connect(this.musicBus);

      // 4. FX: Stereo Delay (Echo)
      this.delayNode = this.ctx.createDelay(2.0);
      this.delayFeedback = this.ctx.createGain();
      const delayFilter = this.ctx.createBiquadFilter();

      this.delayNode.delayTime.value = 60 / this.context.bpm * 0.75; // Dotted 8th
      this.delayFeedback.gain.value = 0.4;
      delayFilter.type = 'lowpass';
      delayFilter.frequency.value = 2000; // Dark echoes

      this.delayNode.connect(delayFilter);
      delayFilter.connect(this.delayFeedback);
      this.delayFeedback.connect(this.delayNode);

      const delayOutput = this.ctx.createGain();
      delayOutput.gain.value = 0.3;
      this.delayNode.connect(delayOutput);
      delayOutput.connect(this.musicBus);

      // Attach Unlock Listeners for iOS
      const events = ['click', 'touchstart', 'touchend', 'keydown'];
      events.forEach(event => {
          window.addEventListener(event, this.handleUnlock, { passive: true, capture: true });
      });
    }
  }

  // Generate a high-quality impulse response for reverb
  private createReverbImpulse(duration: number) {
      if (!this.ctx) return null;
      const rate = this.ctx.sampleRate;
      const length = rate * duration;
      const impulse = this.ctx.createBuffer(2, length, rate);
      const L = impulse.getChannelData(0);
      const R = impulse.getChannelData(1);

      for (let i = 0; i < length; i++) {
          const n = i / length;
          // Exponential decay with noise
          const env = Math.pow(1 - n, 2.5); 
          L[i] = (Math.random() * 2 - 1) * env;
          R[i] = (Math.random() * 2 - 1) * env;
      }
      return impulse;
  }

  // --- PUBLIC CONTROLS ---

  public async preload() {
    this.init();
    if (this.ctx && this.ctx.state === 'suspended') {
        try {
            await this.ctx.resume();
        } catch (e) {
            console.warn("Audio Context resume failed during preload", e);
        }
    }
    return Promise.resolve();
  }

  public setMusicMuted(muted: boolean) {
      this.isMusicMuted = muted;
      if (this.musicBus && this.ctx) {
          // Instant mute, smooth unmute
          const time = this.ctx.currentTime;
          if (muted) {
              this.musicBus.gain.setValueAtTime(0, time);
              // Kill the loop to save CPU and ensure clean restart (immediate stop)
              this.stopMusic(true);
          } else {
              this.musicBus.gain.setValueAtTime(0, time);
              this.musicBus.gain.linearRampToValueAtTime(0.5, time + 0.3);
              // Restart logic if not running
              if (!this.musicRunning) {
                  this.startMusic();
              }
          }
      }
  }

  public setSfxMuted(muted: boolean) {
      this.isSfxMuted = muted;
      if (this.sfxBus && this.ctx) {
          this.sfxBus.gain.setValueAtTime(muted ? 0 : 0.5, this.ctx.currentTime);
      }
  }

  public toggleMusic() { this.setMusicMuted(!this.isMusicMuted); }
  public toggleSfx() { this.setSfxMuted(!this.isSfxMuted); }

  public updateMusic(credits: number, maxThreshold: number) {
      // Dynamic Intensity based on player wealth/progress
      const ratio = Math.min(1, credits / Math.max(1, maxThreshold));
      // Gradually shift intensity (0.5 to 1.0) based on progress
      this.context.intensity = 0.4 + (ratio * 0.6);
  }

  // --- COMPOSITION ENGINE ---

  private regenerateComposition() {
      // Pick a random key
      const roots = Object.values(ROOT_FREQUENCIES);
      const root = roots[Math.floor(Math.random() * roots.length)];

      // Pick a scale flavor
      const scaleKeys = Object.keys(SCALES) as (keyof typeof SCALES)[];
      const scaleKey = scaleKeys[Math.floor(Math.random() * scaleKeys.length)];
      const scale = SCALES[scaleKey];

      // Pick BPM (Ambient slow or Driving fast)
      const bpm = 90 + Math.random() * 40;

      // Generate Chord Progression (4 chords, using scale degrees)
      const prog = [];
      prog.push([0, 2, 4]); // Tonic triad
      for(let i=0; i<3; i++) {
          const rootDegree = Math.floor(Math.random() * 7);
          prog.push([rootDegree, (rootDegree + 2) % 7, (rootDegree + 4) % 7]);
      }

      this.context = {
          rootFreq: root,
          scale: scale,
          bpm: bpm,
          chordProgression: prog,
          currentChordIndex: 0,
          intensity: 0.5
      };

      // Reset Arrange
      this.arrangementState = { section: Section.INTRO, barCount: 0, totalBars: 0 };
      this.generatePatterns();

      if (this.delayNode && this.ctx) {
           this.delayNode.delayTime.setValueAtTime(60 / bpm * 0.75, this.ctx.currentTime);
      }
  }

  private generatePatterns() {
      // Procedural 16-step patterns

      // Kick: Euclidean-ish distribution
      this.patterns.kick = new Array(16).fill(false);
      for(let i=0; i<16; i+=4) this.patterns.kick[i] = true; // 4/4 base
      if (Math.random() > 0.5) this.patterns.kick[14] = true; // Syncopation

      // Hats: 16ths or 8ths
      this.patterns.hat = new Array(16).fill(false);
      for(let i=2; i<16; i+=4) this.patterns.hat[i] = true; // Offbeat open
      if (this.context.intensity > 0.6) {
           for(let i=0; i<16; i+=2) if (!this.patterns.hat[i]) this.patterns.hat[i] = Math.random() > 0.7; // 8th fill
      }

      // Bass: Follows Root of current chord usually
      this.patterns.bass = new Array(16).fill(-1);
      this.patterns.bass[0] = 0; // Root on 1
      this.patterns.bass[10] = 0; // Root on 3.5
      if (Math.random() > 0.5) this.patterns.bass[14] = 4; // Fifth on end

      // Arp: Random walk in scale
      this.patterns.arp = new Array(16).fill(-1);
      for(let i=0; i<16; i++) {
          if (Math.random() > 0.6) {
              this.patterns.arp[i] = Math.floor(Math.random() * 7); // Random scale degree
          }
      }
  }

  // --- AUDIO SCHEDULER ---

  public startMusic() {
      // Cancel any pending lazy stop
      if (this.stopTimerID !== null) {
          window.clearTimeout(this.stopTimerID);
          this.stopTimerID = null;
      }

      this.init();
      if (!this.ctx || this.isMusicMuted) return;

      // If already running, do NOT restart/regenerate or start a new scheduler
      if (this.musicRunning) {
          if (this.ctx.state === 'suspended') {
              this.ctx.resume().catch(e => console.error("Could not resume audio context", e));
          }
          return;
      }

      // If we are resetting completely, gen new track
      if (this.arrangementState.totalBars === 0) {
          this.regenerateComposition();
      }

      this.musicRunning = true;
      this.schedulerId++; // Increment ID so pending timeouts from old loops cancel themselves
      const currentId = this.schedulerId;

      this.nextNoteTime = this.ctx.currentTime + 0.1;
      this.current16thNote = 0;

      this.scheduler(currentId);
  }

  public stopMusic(immediate: boolean = false) {
      if (this.stopTimerID !== null) {
          window.clearTimeout(this.stopTimerID);
          this.stopTimerID = null;
      }

      const triggerStop = () => {
          this.musicRunning = false;
          this.schedulerId++; // Invalidate any pending loops
          if (this.timerID !== null) {
              window.clearTimeout(this.timerID);
              this.timerID = null;
          }
          this.stopTimerID = null;
      };

      if (immediate) {
          triggerStop();
      } else {
          this.stopTimerID = window.setTimeout(triggerStop, 350);
      }
  }

  private scheduler(runId: number) {
      // Must verify musicRunning state AND runId to handle race conditions
      if (!this.musicRunning || !this.ctx || runId !== this.schedulerId) return;

      while (this.nextNoteTime < this.ctx.currentTime + this.scheduleAheadTime) {
          this.scheduleNote(this.current16thNote, this.nextNoteTime);
          this.nextNoteTime += 0.25 * 60.0 / this.context.bpm; // Add quarter note / 4
          this.current16thNote++;
          if (this.current16thNote === 16) {
              this.current16thNote = 0;
              this.handleBarChange();
          }
      }
      this.timerID = window.setTimeout(() => this.scheduler(runId), this.lookahead);
  }

  private handleBarChange() {
      this.arrangementState.barCount++;
      this.arrangementState.totalBars++;

      // Change Chord every bar
      this.context.currentChordIndex = (this.context.currentChordIndex + 1) % this.context.chordProgression.length;

      // Arrangement Logic (Simplified Director)
      const bars = this.arrangementState.barCount;
      const section = this.arrangementState.section;

      if (section === Section.INTRO && bars > 4) {
          this.arrangementState.section = Section.BUILD;
          this.arrangementState.barCount = 0;
      } else if (section === Section.BUILD && bars > 4) {
          this.arrangementState.section = Section.MAIN;
          this.arrangementState.barCount = 0;
          this.generatePatterns(); // Fresh patterns for drop
      } else if (section === Section.MAIN && bars > 16) {
          this.arrangementState.section = Section.BREAKDOWN;
          this.arrangementState.barCount = 0;
      } else if (section === Section.BREAKDOWN && bars > 8) {
          this.arrangementState.section = Section.MAIN;
          this.arrangementState.barCount = 0;
          this.generatePatterns(); // Change it up
      }
  }

  // --- SOUND GENERATION ---

  private scheduleNote(beatNumber: number, time: number) {
      if (this.isMusicMuted) return;

      const sect = this.arrangementState.section;

      // 1. KICK (Punchy)
      if ((sect === Section.MAIN || (sect === Section.BUILD && beatNumber % 2 === 0))) {
          if (this.patterns.kick[beatNumber]) {
              this.triggerKick(time);
          }
      }

      // 2. BASS (FM Synthesis)
      if (sect === Section.MAIN || (sect === Section.BUILD && this.arrangementState.barCount > 2)) {
          const bassNote = this.patterns.bass[beatNumber];
          if (bassNote !== -1) {
              const chord = this.context.chordProgression[this.context.currentChordIndex];
              const degree = chord[0]; 
              const freq = this.getFreq(degree, 0); // Bass octave 0
              this.triggerFMBass(time, freq);
          }
      }

      // 3. PAD (Atmospheric Chords)
      if (beatNumber === 0) { // On downbeat
          const chord = this.context.chordProgression[this.context.currentChordIndex];
          this.triggerPadChord(time, chord);
      }

      // 4. HI-HATS
      if (sect !== Section.INTRO && sect !== Section.BREAKDOWN) {
          if (this.patterns.hat[beatNumber]) {
              const accent = beatNumber % 4 === 2; // Offbeat accent
              this.triggerHat(time, accent);
          }
      }

      // 5. ARP (Plucky)
      if (sect !== Section.BUILD) {
          const arpDegree = this.patterns.arp[beatNumber];
          if (arpDegree !== -1) {
              const freq = this.getFreq(arpDegree, 3); // High octave
              this.triggerArp(time, freq);
          }
      }
  }

  // --- SYNTHESIS ENGINES ---

  private getFreq(scaleDegree: number, octaveOffset: number): number {
      const scaleLen = this.context.scale.length;
      const octave = Math.floor(scaleDegree / scaleLen) + octaveOffset;
      const index = Math.abs(scaleDegree % scaleLen);
      const semitones = this.context.scale[index] + (octave * 12);
      return this.context.rootFreq * Math.pow(2, semitones / 12);
  }

  private triggerKick(time: number) {
      if (!this.ctx || !this.musicBus) return;

      const osc = this.ctx.createOscillator();
      const gain = this.ctx.createGain();

      osc.frequency.setValueAtTime(150, time);
      osc.frequency.exponentialRampToValueAtTime(0.01, time + 0.5);

      gain.gain.setValueAtTime(1.0, time);
      gain.gain.exponentialRampToValueAtTime(0.01, time + 0.5);

      osc.connect(gain);
      gain.connect(this.musicBus);
      osc.start(time);
      osc.stop(time + 0.5);

      osc.onended = () => { osc.disconnect(); gain.disconnect(); };
  }

  private triggerFMBass(time: number, freq: number) {
      if (!this.ctx || !this.musicBus) return;

      // Carrier
      const car = this.ctx.createOscillator();
      car.type = 'sine';
      car.frequency.value = freq;

      // Modulator
      const mod = this.ctx.createOscillator();
      mod.type = 'square'; // Gritty
      mod.frequency.value = freq * 0.5; // Sub-octave mod

      const modGain = this.ctx.createGain();
      // FM Index envelope
      modGain.gain.setValueAtTime(500, time); 
      modGain.gain.exponentialRampToValueAtTime(1, time + 0.3);

      mod.connect(modGain);
      modGain.connect(car.frequency);

      // Amp Envelope
      const amp = this.ctx.createGain();
      amp.gain.setValueAtTime(0, time);
      amp.gain.linearRampToValueAtTime(0.6, time + 0.02);
      amp.gain.exponentialRampToValueAtTime(0.01, time + 0.4);

      // Lowpass Filter for "wub"
      const filter = this.ctx.createBiquadFilter();
      filter.type = 'lowpass';
      filter.frequency.setValueAtTime(300, time);
      filter.frequency.exponentialRampToValueAtTime(100, time + 0.3);

      car.connect(filter);
      filter.connect(amp);
      amp.connect(this.musicBus);

      car.start(time);
      mod.start(time);
      car.stop(time + 0.5);
      mod.stop(time + 0.5);

      car.onended = () => { car.disconnect(); mod.disconnect(); modGain.disconnect(); amp.disconnect(); filter.disconnect(); };
  }

  private triggerPadChord(time: number, chordDegrees: number[]) {
      if (!this.ctx || !this.musicBus) return;

      const attack = 1.5;
      const release = 1.5;
      const dur = (60 / this.context.bpm) * 4; // 1 bar

      chordDegrees.forEach((deg, _i) => {
          const freq = this.getFreq(deg, 2); // Mid range

          const osc1 = this.ctx!.createOscillator();
          osc1.type = 'sawtooth';
          osc1.frequency.value = freq;
          osc1.detune.value = -10 + (Math.random() * 20); // Thick detune

          const osc2 = this.ctx!.createOscillator();
          osc2.type = 'triangle';
          osc2.frequency.value = freq;
          osc2.detune.value = -5 + (Math.random() * 10);

          const filter = this.ctx!.createBiquadFilter();
          filter.type = 'lowpass';
          filter.frequency.value = 400 + (Math.random() * 200);
          filter.Q.value = 1;

          // Slight filter movement LFO
          const lfo = this.ctx!.createOscillator();
          lfo.frequency.value = 0.2; // Slow breathe
          const lfoGain = this.ctx!.createGain();
          lfoGain.gain.value = 200;
          lfo.connect(lfoGain);
          lfoGain.connect(filter.frequency);

          const gain = this.ctx!.createGain();
          gain.gain.setValueAtTime(0, time);
          gain.gain.linearRampToValueAtTime(0.08, time + attack);
          gain.gain.setValueAtTime(0.08, time + dur - release);
          gain.gain.linearRampToValueAtTime(0, time + dur);

          osc1.connect(filter);
          osc2.connect(filter);
          filter.connect(gain);

          // Send to Reverb heavily
          if (this.reverbNode) gain.connect(this.reverbNode);
          else gain.connect(this.musicBus!);

          osc1.start(time);
          osc2.start(time);
          lfo.start(time);

          const stopTime = time + dur + 0.1;
          osc1.stop(stopTime);
          osc2.stop(stopTime);
          lfo.stop(stopTime);

          osc1.onended = () => { osc1.disconnect(); osc2.disconnect(); lfo.disconnect(); lfoGain.disconnect(); filter.disconnect(); gain.disconnect(); };
      });
  }

  private triggerArp(time: number, freq: number) {
      if (!this.ctx || !this.musicBus) return;

      const osc = this.ctx.createOscillator();
      osc.type = 'sine'; // Plucky sine
      osc.frequency.value = freq;

      const gain = this.ctx.createGain();
      gain.gain.setValueAtTime(0, time);
      gain.gain.linearRampToValueAtTime(0.1, time + 0.01);
      gain.gain.exponentialRampToValueAtTime(0.001, time + 0.2);

      osc.connect(gain);
      // Send to Delay
      if (this.delayNode) gain.connect(this.delayNode);
      gain.connect(this.musicBus);

      osc.start(time);
      osc.stop(time + 0.25);

      osc.onended = () => { osc.disconnect(); gain.disconnect(); };
  }

  private triggerHat(time: number, accent: boolean) {
      if (!this.ctx || !this.musicBus || !this.whiteNoiseBuffer) return;

      const noise = this.ctx.createBufferSource();
      noise.buffer = this.whiteNoiseBuffer;

      const filter = this.ctx.createBiquadFilter();
      filter.type = 'highpass';
      filter.frequency.value = 8000;

      const gain = this.ctx.createGain();
      gain.gain.setValueAtTime(accent ? 0.15 : 0.05, time);
      gain.gain.exponentialRampToValueAtTime(0.001, time + (accent ? 0.05 : 0.03));

      noise.connect(filter);
      filter.connect(gain);
      gain.connect(this.musicBus);

      noise.start(time);
      noise.stop(time + (accent ? 0.05 : 0.03));
      noise.onended = () => { noise.disconnect(); filter.disconnect(); gain.disconnect(); };
  }

  // --- SFX METHODS ---
  public play(type: SoundType) {
    if (this.isSfxMuted) return;
    this.init();
    if (!this.ctx || !this.sfxBus) return;

    const t = this.ctx.currentTime;

    const playOsc = (freq: number, type: OscillatorType, dur: number, vol: number, startTime: number = t) => {
        const osc = this.ctx!.createOscillator();
        const g = this.ctx!.createGain();
        osc.type = type;
        osc.frequency.setValueAtTime(freq, startTime);
        g.gain.setValueAtTime(vol, startTime);
        g.gain.exponentialRampToValueAtTime(0.01, startTime + dur);
        osc.connect(g);
        g.connect(this.sfxBus!);
        osc.start(startTime);
        osc.stop(startTime + dur);

        osc.onended = () => { osc.disconnect(); g.disconnect(); };
    };

    switch (type) {
      case 'UI_CLICK': playOsc(800, 'triangle', 0.1, 0.1); break;
      case 'UI_HOVER': playOsc(400, 'sine', 0.05, 0.02); break;
      case 'ERROR': playOsc(150, 'sawtooth', 0.2, 0.1); break;
      case 'SUCCESS': 
        playOsc(523, 'sine', 0.3, 0.1, t); 
        playOsc(659, 'sine', 0.3, 0.1, t + 0.1);
        break;
      case 'COIN': playOsc(1200, 'sine', 0.4, 0.05); break;
      case 'MOVE': 
        if (this.whiteNoiseBuffer) {
            const src = this.ctx.createBufferSource();
            src.buffer = this.whiteNoiseBuffer;
            const f = this.ctx.createBiquadFilter();
            f.type = 'lowpass'; f.frequency.setValueAtTime(500, t); f.frequency.linearRampToValueAtTime(100, t+0.1);
            const g = this.ctx.createGain();
            g.gain.setValueAtTime(0.1, t); g.gain.linearRampToValueAtTime(0, t+0.1);
            src.connect(f); f.connect(g); g.connect(this.sfxBus); 
            src.start(t);
            src.stop(t + 0.1);
            src.onended = () => { src.disconnect(); f.disconnect(); g.disconnect(); };
        }
        break;
      case 'LEVEL_UP':
         playOsc(440, 'triangle', 0.6, 0.1, t);
         playOsc(880, 'triangle', 0.6, 0.1, t + 0.2);
         break;
      case 'COLLAPSE': playOsc(60, 'sawtooth', 0.6, 0.3); break;
      case 'CRACK': playOsc(300, 'square', 0.05, 0.2); break;
      case 'FIREWORK': {
          if (this.whiteNoiseBuffer) {
              const noise = this.ctx.createBufferSource();
              noise.buffer = this.whiteNoiseBuffer;

              const filter = this.ctx.createBiquadFilter();
              filter.type = 'lowpass';
              filter.frequency.setValueAtTime(1200, t);
              filter.frequency.exponentialRampToValueAtTime(50, t + 0.4);

              const gain = this.ctx.createGain();
              gain.gain.setValueAtTime(0.3, t);
              gain.gain.exponentialRampToValueAtTime(0.01, t + 0.4);

              noise.connect(filter);
              filter.connect(gain);
              gain.connect(this.sfxBus);
              noise.start(t);
              noise.stop(t + 0.5);
              noise.onended = () => { noise.disconnect(); filter.disconnect(); gain.disconnect(); };
          }
          break;
      }
      case 'TELEPORT': {
         const oscBeam = this.ctx.createOscillator();
         const gainBeam = this.ctx.createGain();

         oscBeam.type = 'triangle';
         oscBeam.frequency.setValueAtTime(150, t);
         oscBeam.frequency.exponentialRampToValueAtTime(1800, t + 0.7);

         gainBeam.gain.setValueAtTime(0, t);
         gainBeam.gain.linearRampToValueAtTime(0.2, t + 0.15);
         gainBeam.gain.exponentialRampToValueAtTime(0.001, t + 0.82);

         const mod = this.ctx.createOscillator();
         mod.frequency.value = 50;
         const modGain = this.ctx.createGain();
         modGain.gain.value = 80;
         mod.connect(modGain);
         modGain.connect(oscBeam.frequency);

         oscBeam.connect(gainBeam);
         gainBeam.connect(this.sfxBus);

         oscBeam.start(t);
         mod.start(t);
         oscBeam.stop(t + 0.82);
         mod.stop(t + 0.82);
         oscBeam.onended = () => { oscBeam.disconnect(); mod.disconnect(); modGain.disconnect(); gainBeam.disconnect(); };

         const chimes = [1046.50, 1318.51, 1567.98, 2093.00];
         chimes.forEach((freq, index) => {
             const chimTime = t + 0.2 + (index * 0.1);
             const oscC = this.ctx!.createOscillator();
             const gainC = this.ctx!.createGain();
             oscC.type = 'sine';
             oscC.frequency.setValueAtTime(freq, chimTime);

             gainC.gain.setValueAtTime(0, chimTime);
             gainC.gain.linearRampToValueAtTime(0.12, chimTime + 0.02);
             gainC.gain.exponentialRampToValueAtTime(0.001, chimTime + 0.45);

             oscC.connect(gainC);
             if (this.reverbNode) {
                 gainC.connect(this.reverbNode);
             } else {
                 gainC.connect(this.sfxBus!);
             }

             oscC.start(chimTime);
             oscC.stop(chimTime + 0.5);
             oscC.onended = () => { oscC.disconnect(); gainC.disconnect(); };
         });
         break;
      }
    }
  }

  public startPortalHum() {
      if (this.isSfxMuted) return;
      this.init();
      if (!this.ctx || !this.sfxBus) return;

      this.stopPortalHum();

      const t = this.ctx.currentTime;

      const osc1 = this.ctx.createOscillator();
      osc1.type = 'sawtooth';
      osc1.frequency.value = 65.41;

      const filter = this.ctx.createBiquadFilter();
      filter.type = 'lowpass';
      filter.frequency.value = 180;

      const lfo = this.ctx.createOscillator();
      lfo.frequency.value = 4;
      const lfoGain = this.ctx.createGain();
      lfoGain.gain.value = 60;

      lfo.connect(lfoGain);
      lfoGain.connect(filter.frequency);

      const gain = this.ctx.createGain();
      gain.gain.setValueAtTime(0, t);
      gain.gain.linearRampToValueAtTime(0.35, t + 1.2);

      osc1.connect(filter);
      filter.connect(gain);
      gain.connect(this.sfxBus);

      osc1.start(t);
      lfo.start(t);

      this.portalHumNode = { osc: osc1, lfo: lfo, filter, lfoGain, gain };
  }

  public stopPortalHum() {
      if (this.portalHumNode) {
          try {
              const { osc, lfo, gain } = this.portalHumNode;
              if (this.ctx) {
                  const t = this.ctx.currentTime;
                  gain.gain.cancelScheduledValues(t);
                  gain.gain.setValueAtTime(gain.gain.value, t);
                  gain.gain.linearRampToValueAtTime(0, t + 0.3);
                  setTimeout(() => {
                      try {
                          osc.stop();
                          lfo.stop();
                          osc.disconnect();
                          lfo.disconnect();
                          gain.disconnect();
                      } catch (e) {}
                  }, 400);
              } else {
                  osc.stop();
                  lfo.stop();
                  osc.disconnect();
                  lfo.disconnect();
                  gain.disconnect();
              }
          } catch (e) {
              console.error("Error stopping portal hum", e);
          }
          this.portalHumNode = null;
      }
  }
}

export const audioService = new AudioService();

import { Hex, HexCoord, Entity, PathResult } from '../types';
import { GAME_CONFIG, getLevelConfig, SAFETY_CONFIG } from '../rules/config';
import { getItemDef } from '../rules/items';
import { getMilestoneModifiers } from '../campaign/milestones.ts';

let storeRef: any = null;
export const registerGameStore = (store: any) => {
  storeRef = store;
};

export const getHexKey = (q: number, r: number): string => `${q},${r}`;
export const getCoordinatesFromKey = (key: string): HexCoord => {
  const [q, r] = key.split(',').map(Number);
  return { q, r };
};

// --- OPTIMIZATION: Cache Math Constants ---
const SQRT_3 = Math.sqrt(3);
const SQRT_3_DIV_2 = SQRT_3 / 2;
const ONE_POINT_FIVE = 1.5;
const DEG_TO_RAD = Math.PI / 180;

export const hexToPixel = (q: number, r: number, rotationDegrees: number = 0): { x: number, y: number } => {
  const size = GAME_CONFIG.HEX_SIZE;

  // Pre-calculate raw grid position without rotation
  const rawX = size * (SQRT_3 * q + SQRT_3_DIV_2 * r);
  const rawY = size * (ONE_POINT_FIVE * r);

  // Fast path: No rotation (common case)
  if (rotationDegrees === 0) {
    return { 
      x: rawX, 
      y: rawY * 0.8 // Apply perspective squash
    };
  }

  // Rotate
  const angleRad = rotationDegrees * DEG_TO_RAD;
  const cos = Math.cos(angleRad);
  const sin = Math.sin(angleRad);

  return { 
    x: rawX * cos - rawY * sin, 
    y: (rawX * sin + rawY * cos) * 0.8 
  };
};

export const cubeDistance = (a: HexCoord, b: HexCoord): number => {
  return (Math.abs(a.q - b.q) + Math.abs(a.q + a.r - b.q - b.r) + Math.abs(a.r - b.r)) / 2;
};

const NEIGHBOR_DIRECTIONS = [
  { q: 1, r: 0 }, { q: 1, r: -1 }, { q: 0, r: -1 }, 
  { q: -1, r: 0 }, { q: -1, r: 1 }, { q: 0, r: 1 }
];

export const getNeighbors = (q: number, r: number): HexCoord[] => {
  const neighbors: HexCoord[] = [];
  for (let i = 0; i < 6; i++) {
    const d = NEIGHBOR_DIRECTIONS[i];
    neighbors.push({ q: q + d.q, r: r + d.r });
  }
  return neighbors;
};

export const getSecondsToGrow = (level: number) => getLevelConfig(level).growthTime;

/**
 * Calculates active multipliers and values based on entity status effects.
 * Iterates through all active statuses to apply stacking effects correctly.
 */
export const getStatusModifiers = (actor: Entity, session?: any): {
  moveCostMultiplier: number;
  fogRadius: number;
  digRewardMultiplier: number;
  exchangeRate: number;
  growthAccelerator: number;
  foundationStrength: number;
  economicMultiplier: number;
  diggerLuck: number;
  doubleDigChance: number;
  reserveCapacitor: number;
  turboRecharge: number;
  entropyResistance: number;
  restorationMaster: number;
} => {
  let moveCostMultiplier = 1.0;
  let fogRadius = 2; // Default: Center + 2 Rings
  let digRewardMultiplier = 1.0;

  let exchangeRate = GAME_CONFIG.EXCHANGE_RATE_COINS_PER_MOVE;
  let growthAccelerator = 0;
  let foundationStrength = 0;
  let economicMultiplier = 1.0;
  let diggerLuck = 0;
  let doubleDigChance = 0;
  let reserveCapacitor = 0;
  let turboRecharge = 0;
  let entropyResistance = 1.0;
  let restorationMaster = 0;

  const isPlayer = actor && (actor.id === 'player' || actor.id === 'player-1' || actor.id.startsWith('player'));
  const upgrades = session?.campaignUpgrades;

  // --- FETCH MILSTONES EXTERNALLY FOR PASSIVES ---
  if (isPlayer) {
      let totalGoldEarned = 0;
      try {
          totalGoldEarned = (storeRef?.getState()?.totalGoldEarned) || session?.totalGoldEarned || 0;
      } catch (e) {
          // Fallback if accessed via tests/headless engine without Zustand
          totalGoldEarned = session?.totalGoldEarned || 0;
      }

      // 0. Economic Milestones Passives (GLOBAL PROGREES)
      if (totalGoldEarned > 0) {
          const milestones = getMilestoneModifiers(totalGoldEarned);
          exchangeRate = Math.max(1, exchangeRate - milestones.extraFuel);
          economicMultiplier += milestones.extraIncomeMult;
          fogRadius += milestones.extraVision;
          reserveCapacitor += milestones.extraRecoveryCharges;
      }

      // 1. Upgrades Tree passives
      if (upgrades) {
          fogRadius += upgrades.scanRadius || 0;
          exchangeRate = Math.max(1, exchangeRate - (upgrades.fuelEfficiency || 0));
          growthAccelerator = upgrades.growthAccelerator || 0;
          foundationStrength = upgrades.foundationStrength || 0;
          economicMultiplier += ((upgrades.economicMultiplier || 0) / 100);
          diggerLuck = upgrades.diggerLuck || 0;
          doubleDigChance += (upgrades.doubleDigChance || 0) / 100;
          reserveCapacitor += upgrades.reserveCapacitor || 0;
          turboRecharge = upgrades.turboRecharge || 0;
          entropyResistance -= ((upgrades.entropyResistance || 0) / 100);
          restorationMaster = upgrades.restorationMaster || 0;
      }
  }

  // --- PASSIVE EQUIPMENT BONUSES ---
  if (actor && actor.equipment) {
      for (const [slot, item] of Object.entries(actor.equipment)) {
          if (!item) continue;
          const itemDef = getItemDef(item.baseId);
          if (!itemDef) continue;

          // 1. Armor item maxHpBonus -> passive reality/entropy decay resistance
          if (itemDef.maxHpBonus) {
              const resScale = itemDef.maxHpBonus * 0.0075; // e.g. 50 maxHP = 37.5% resistance
              entropyResistance = Math.max(0.1, entropyResistance - resScale);
              foundationStrength += Math.floor(itemDef.maxHpBonus / 10);
          }

          // 2. Boots item maxEnergyBonus -> moveCostMultiplier reduction & turbo recharge
          if (itemDef.maxEnergyBonus) {
              const energyScale = itemDef.maxEnergyBonus * 0.01; // e.g. 15 energy = 15% cheaper moves
              moveCostMultiplier = Math.max(0.5, moveCostMultiplier - energyScale);
              turboRecharge += Math.floor(itemDef.maxEnergyBonus / 3);
          }

          // 3. Drill/tools reward multiplier
          if (itemDef.idPrefix.includes('drill') || itemDef.idPrefix.includes('pickaxe') || slot === 'tool') {
              if (itemDef.idPrefix.includes('plasma_drill')) {
                  digRewardMultiplier *= 1.5;
                  doubleDigChance += 0.25;
              } else if (itemDef.idPrefix.includes('hornet_drill')) {
                  digRewardMultiplier *= 1.8;
                  doubleDigChance += 0.35;
              } else if (itemDef.idPrefix.includes('pickaxe')) {
                  digRewardMultiplier *= 1.25;
                  doubleDigChance += 0.50;
              } else {
                  digRewardMultiplier *= 1.15;
                  diggerLuck += 1;
              }
          }

          // 4. Rings & Necklaces (economy multiplier)
          if (slot === 'ring' || slot === 'necklace' || itemDef.idPrefix.includes('ring') || itemDef.idPrefix.includes('necklace')) {
              economicMultiplier += 0.20; // +20% coins
              exchangeRate = Math.max(1, exchangeRate - 1); // 1 credit cheaper move recharge
          }

          // 5. Helmets & scannable visors (sensor range boost)
          if (slot === 'head' || itemDef.idPrefix.includes('visor') || itemDef.idPrefix.includes('scanner') || itemDef.idPrefix.includes('helm')) {
              if (itemDef.idPrefix.includes('scanner') || itemDef.idPrefix.includes('visor')) {
                  fogRadius += 2;
              } else {
                  fogRadius += 1;
              }
          }

          // 6. Artifact slots (uncommon/rare/legendary components)
          if (slot === 'artifact' || itemDef.equipSlot === 'artifact') {
              if (itemDef.idPrefix === 'cargo_prism') {
                  growthAccelerator += 2;
              } else if (itemDef.idPrefix === 'chronos_core') {
                  growthAccelerator += 4;
                  turboRecharge += 5;
              } else if (itemDef.idPrefix === 'apex_core') {
                  growthAccelerator += 5;
                  entropyResistance = Math.max(0.05, entropyResistance - 0.5);
                  economicMultiplier += 0.5;
              } else if (itemDef.idPrefix === 'midas_chip') {
                  economicMultiplier += 0.75;
              } else if (itemDef.idPrefix === 'matter_prism') {
                  growthAccelerator += 3;
              } else if (itemDef.idPrefix === 'architect_nanites') {
                  foundationStrength += 3;
                  growthAccelerator += 3;
              } else if (itemDef.idPrefix === 'stability_scanner') {
                  entropyResistance = Math.max(0.1, entropyResistance - 0.3);
              }
          }
      }
  }

  if (!actor || !actor.activeStatuses) return { moveCostMultiplier, fogRadius, digRewardMultiplier, exchangeRate, growthAccelerator, foundationStrength, economicMultiplier, diggerLuck, doubleDigChance, reserveCapacitor, turboRecharge, entropyResistance, restorationMaster };

  const now = Date.now();
  let hasTunnelVision = false;

  for (const status of actor.activeStatuses) {
      if (status.expiresAt && status.expiresAt <= now) continue;

      switch (status.type) {
          case 'STATUS_FATIGUE':
              // Upgrade: Fatigue Resistance reduces the penalty
              let fatigueMult = 2.0;
              if (isPlayer && upgrades && upgrades.fatigueResistance) {
                  fatigueMult -= (upgrades.fatigueResistance * 0.25); // e.g. 2.0 -> 1.75 -> 1.5
              }
              moveCostMultiplier *= fatigueMult;
              break;
          case 'STATUS_GOLD_RUSH':
              digRewardMultiplier *= 2.0;
              break;
          case 'STATUS_SCANNER_BUFF':
              fogRadius += 2; // Stacks with multiple scanners
              break;
          case 'STATUS_TUNNEL_VISION':
              hasTunnelVision = true;
              break;
          // Add other status effects here as needed
      }
  }

  // Tunnel Vision overrides all scanner buffs
  if (hasTunnelVision) {
      fogRadius = 0; // Only current hex visible (Center only)
  }

  return { moveCostMultiplier, fogRadius, digRewardMultiplier, exchangeRate, growthAccelerator, foundationStrength, economicMultiplier, diggerLuck, doubleDigChance, reserveCapacitor, turboRecharge, entropyResistance, restorationMaster };
};

/**
 * Min-Heap Priority Queue implementation for O(log n) retrievals
 */
class PriorityQueue<T> {
  private _heap: { node: T; weight: number }[] = [];

  get length(): number {
    return this._heap.length;
  }

  push(node: T, weight: number): void {
    this._heap.push({ node, weight });
    this._bubbleUp();
  }

  pop(): T | undefined {
    if (this.length === 0) return undefined;
    const top = this._heap[0];
    const bottom = this._heap.pop();
    if (this._heap.length > 0 && bottom) {
      this._heap[0] = bottom;
      this._sinkDown();
    }
    return top.node;
  }

  private _bubbleUp(): void {
    let index = this._heap.length - 1;
    const element = this._heap[index];
    while (index > 0) {
      const parentIndex = Math.floor((index - 1) / 2);
      const parent = this._heap[parentIndex];
      if (element.weight >= parent.weight) break;
      this._heap[parentIndex] = element;
      this._heap[index] = parent;
      index = parentIndex;
    }
  }

  private _sinkDown(): void {
    let index = 0;
    const length = this._heap.length;
    const element = this._heap[0];
    while (true) {
      const leftChildIdx = 2 * index + 1;
      const rightChildIdx = 2 * index + 2;
      let leftChild, rightChild;
      let swap = null;

      if (leftChildIdx < length) {
        leftChild = this._heap[leftChildIdx];
        if (leftChild.weight < element.weight) {
          swap = leftChildIdx;
        }
      }

      if (rightChildIdx < length) {
        rightChild = this._heap[rightChildIdx];
        if (
          (swap === null && rightChild.weight < element.weight) ||
          (swap !== null && leftChild && rightChild.weight < leftChild.weight)
        ) {
          swap = rightChildIdx;
        }
      }

      if (swap === null) break;
      this._heap[index] = this._heap[swap];
      this._heap[swap] = element;
      index = swap;
    }
  }
}

/**
 * Optimized A* Pathfinding using Min-Heap
 */
export const findPath = (
  start: HexCoord, 
  end: HexCoord, 
  grid: Record<string, Hex>, 
  rank: number, 
  obstacles: HexCoord[],
  hasVoidCore?: boolean,
  ignoreAllRules?: boolean,
  isBot?: boolean,
  isDefenseMode?: boolean
): PathResult => {
  const startKey = getHexKey(start.q, start.r);
  const endKey = getHexKey(end.q, end.r);

  // 1. Immediate checks - Return empty array if already at destination (Success, no movement needed)
  if (startKey === endKey) {
    return { path: [] };
  }

  // DESTINATION VALIDITY CHECK
  const endHex = grid[endKey];
  if (endHex && endHex.structureType === 'VOID') {
    return { path: null, reason: 'VOID' }; // Cannot move into a hole
  }

  // Quick pre-check distance to avoid searching impossible paths
  if (cubeDistance(start, end) > SAFETY_CONFIG.MAX_PATH_LENGTH) {
    return { path: null, reason: 'TOO_FAR' };
  }

  // O(1) Obstacle Lookup
  const obsKeys = new Set(obstacles.map(o => getHexKey(o.q, o.r)));
  if (obsKeys.has(endKey)) {
    return { path: null, reason: 'OBSTACLE' };
  }

  // 2. Setup Data Structures
  const openSet = new PriorityQueue<string>();
  const cameFrom = new Map<string, HexCoord>();
  const gScore = new Map<string, number>();

  // Initialize
  gScore.set(startKey, 0);
  openSet.push(startKey, cubeDistance(start, end));

  let iterations = 0;
  let blockedByRank = false;
  let blockedByHeight = false;

  // 3. Main Loop
  while (openSet.length > 0) {
    // Safety Break
    if (iterations++ > SAFETY_CONFIG.MAX_SEARCH_ITERATIONS) {
      return { path: null, reason: 'TIMEOUT' };
    }

    const currentKey = openSet.pop()!;

    // Safety: Path length check during exploration
    if ((gScore.get(currentKey) || 0) > SAFETY_CONFIG.MAX_PATH_LENGTH) continue;

    if (currentKey === endKey) {
      // Reconstruct Path
      const path: HexCoord[] = [];
      let currKey = endKey;
      while (currKey !== startKey) {
        const coords = getCoordinatesFromKey(currKey);
        path.unshift(coords);
        const parent = cameFrom.get(currKey);
        if (!parent) break; // Should not happen if path exists
        currKey = getHexKey(parent.q, parent.r);
      }
      return { path };
    }

    const currentCoord = getCoordinatesFromKey(currentKey);
    const currentHex = grid[currentKey];
    const currentLevel = currentHex ? currentHex.currentLevel : 0;

    // Evaluate Neighbors
    const neighbors = getNeighbors(currentCoord.q, currentCoord.r);

    for (const neighbor of neighbors) {
      const nKey = getHexKey(neighbor.q, neighbor.r);

      if (obsKeys.has(nKey)) continue;

      const neighborHex = grid[nKey];

      // -- Game Rules --
      if (!ignoreAllRules) {
        // 0. Void Check: Cannot enter a destroyed hex
        if (neighborHex && neighborHex.structureType === 'VOID') continue;

        // 1. Rank Check: Cannot enter hex higher than player rank
        if (neighborHex && neighborHex.currentLevel > rank) {
          blockedByRank = true;
          continue; 
        }

        // 2. Height/Jump Check: Cannot jump more than 1 level difference
        const nextLevel = neighborHex ? neighborHex.currentLevel : 0;
        if (!hasVoidCore && Math.abs(currentLevel - nextLevel) > 1) {
          blockedByHeight = true;
          continue;
        }

        // Siege mode check: Bots can only move on hexes that are lowered to level 1 and below
        if (isBot) {
          const activeDefenseMode = isDefenseMode !== undefined ? isDefenseMode : !!storeRef?.getState()?.session?.defense?.isDefenseMode;
          if (activeDefenseMode && neighborHex && neighborHex.currentLevel > 1) {
            // Allow the destination/target node of the path itself to be level > 1 
            // so the bot can pathfind adjacent to it
            const isDestination = nKey === endKey;
            if (!isDestination) {
              continue;
            }
          }
        }
      }

      // -- Cost Calculation --
      // Update logic: Positive (>1) costs level. Negative/Flat (<2) costs 1.
      const level = neighborHex ? neighborHex.currentLevel : 0;
      const moveCost = hasVoidCore ? 1 : (level > 1 ? level : 1);

      const tentativeG = (gScore.get(currentKey) ?? Infinity) + moveCost;

      if (tentativeG < (gScore.get(nKey) ?? Infinity)) {
        cameFrom.set(nKey, currentCoord);
        gScore.set(nKey, tentativeG);

        const fScore = tentativeG + cubeDistance(neighbor, end);
        openSet.push(nKey, fScore);
      }
    }
  }

  // No path found
  let finalReason = 'BLOCKED';
  if (blockedByRank) finalReason = 'RANK';
  if (blockedByHeight) finalReason = 'STEEP';

  return { path: null, reason: finalReason };
};

/**
 * Finds the optimal route for siege bots to reach the player core (0,0).
 * Chooses the fastest route taking into account standard movement,
 * lowering high hexes (player walls) using DIG, and raising low hexes using UPGRADE.
 */
export const findSiegePath = (
  start: HexCoord, 
  end: HexCoord, 
  grid: Record<string, Hex>
): PathResult => {
  const startKey = getHexKey(start.q, start.r);
  const endKey = getHexKey(end.q, end.r);

  if (startKey === endKey) {
    return { path: [] };
  }

  const endHex = grid[endKey];
  if (endHex && endHex.structureType === 'VOID') {
    return { path: null, reason: 'VOID' };
  }

  if (cubeDistance(start, end) > SAFETY_CONFIG.MAX_PATH_LENGTH) {
    return { path: null, reason: 'TOO_FAR' };
  }

  const openSet = new PriorityQueue<string>();
  const cameFrom = new Map<string, HexCoord>();
  const gScore = new Map<string, number>();

  gScore.set(startKey, 0);
  openSet.push(startKey, cubeDistance(start, end));

  let iterations = 0;

  while (openSet.length > 0) {
    if (iterations++ > SAFETY_CONFIG.MAX_SEARCH_ITERATIONS) {
      return { path: null, reason: 'TIMEOUT' };
    }

    const currentKey = openSet.pop()!;
    // Allow slightly higher path costs because of digging/upgrading
    if ((gScore.get(currentKey) || 0) > SAFETY_CONFIG.MAX_PATH_LENGTH * 8) continue;

    if (currentKey === endKey) {
      const path: HexCoord[] = [];
      let currKey = endKey;
      while (currKey !== startKey) {
        const coords = getCoordinatesFromKey(currKey);
        path.unshift(coords);
        const parent = cameFrom.get(currKey);
        if (!parent) break;
        currKey = getHexKey(parent.q, parent.r);
      }
      return { path };
    }

    const currentCoord = getCoordinatesFromKey(currentKey);
    const currentHex = grid[currentKey];
    const currentLevel = currentHex ? currentHex.currentLevel : 0;

    const neighbors = getNeighbors(currentCoord.q, currentCoord.r);

    for (const neighbor of neighbors) {
      const nKey = getHexKey(neighbor.q, neighbor.r);
      const neighborHex = grid[nKey];

      if (!neighborHex) continue;
      if (neighborHex.structureType === 'VOID') continue;

      const neighborLevel = neighborHex.currentLevel;

      // Base weight: 1 point for moving
      let stepCost = 1;

      // 1. Is it a player wall or elevated tile (level > 1)?
      if (neighborLevel > 1) {
        // Lowering player walls takes digs. Each dig costs 5 weight units.
        const digsNeeded = neighborLevel - 1;
        stepCost += digsNeeded * 5;
      }

      // 2. Is there a steep height jump?
      const diff = neighborLevel - currentLevel;
      if (Math.abs(diff) > 1) {
        if (diff > 1) {
          // Steep uphill: needs to be carved down (digs)
          const digsNeeded = neighborLevel - (currentLevel + 1);
          stepCost += digsNeeded * 5;
        } else {
          // Steep downhill: needs to be built up (upgrades)
          const upgradesNeeded = (currentLevel - 1) - neighborLevel;
          stepCost += upgradesNeeded * 5;
        }
      }

      const tentativeG = (gScore.get(currentKey) ?? Infinity) + stepCost;

      if (tentativeG < (gScore.get(nKey) ?? Infinity)) {
        cameFrom.set(nKey, currentCoord);
        gScore.set(nKey, tentativeG);

        const fScore = tentativeG + cubeDistance(neighbor, end);
        openSet.push(nKey, fScore);
      }
    }
  }

  return { path: null, reason: 'BLOCKED' };
};

